'use strict';
let recoveryAssets=null,operationsBusy=false,operationsError='';
function ops(){if(!state.ops)state.ops={feedback:[],versions:{},champion:'multisource-rf-v2',previous:null,candidate:null,canary:null,jobs:[],auto:true,lastAttempt:0,lastFeedbackCount:0};return state.ops}
function artifact(id){return ops().versions[id]?.artifact||null}
function currentThreshold(){return effectiveThreshold()}
function performance(){const rows=ops().feedback.filter(r=>r.observedFlag!==undefined&&r.observedModel===ops().champion).map(r=>({...r,x:[r.observedFlag?1:0]}));return RecoveryEngine.metrics(rows,x=>x[0],.5)}
function readiness(){if(!trained||!recoveryAssets)return {ok:false,train:[],validation:[],message:operationsError||'Loading recovery reference assets'};return RecoveryEngine.ready(ops().feedback,recoveryAssets)}
function deterioration(){if(!trained||!recoveryAssets)return {confirmed:false,message:'Loading baseline'};const p=performance(),reference=RecoveryEngine.metrics(recoveryAssets.historical_gate,x=>RecoveryEngine.probability(trained,artifact(ops().champion),x,URLModel),currentThreshold());const limit=Math.max(.15,reference.error+.05);return {confirmed:p.n>=30&&p.error>limit,metrics:p,limit,message:p.n<30?`${p.n}/30 reviewed predictions; minimum evidence not reached`:`Reviewed error ${(p.error*100).toFixed(1)}%; trigger above ${(limit*100).toFixed(1)}%`}}
const previousScore=scoreURL;
scoreURL=function(raw){const row=previousScore(raw);const o=ops();let version=o.champion,servedBy='champion';if(o.canary&&o.candidate){const random=crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;if(random<o.canary.weight){version=o.candidate;servedBy='candidate'}o.canary.requests++;if(servedBy==='candidate')o.canary.candidateRequests++}const score=RecoveryEngine.probability(trained,artifact(version),row.features,URLModel)*100;return {...row,score,flag:score>=effectiveThreshold()*100,threshold:effectiveThreshold()*100,model:version,servedBy}}
decision=function(){const o=ops(),r=readiness(),d=deterioration();if(operationsBusy)return {status:'Training and evaluating',message:'A real optimization job is running on reviewed training records and historical replay.',action:'Wait for evaluation'};if(o.canary)return {status:'Canary running',message:'New requests are actually routed between model versions. Promotion waits for new reviewed evidence.',action:'Review canary evidence'};if(o.candidate)return {status:'Candidate passed gates',message:'Independent gate results are recorded below. The candidate is ready for a local serving trial.',action:'Start canary'};if(!r.ok)return {status:ops().feedback.length?'More reviewed labels needed':'Awaiting reviewed labels',message:`Need 20 training and 10 separate validation URLs, with both classes in each. Current: ${r.train.length} training, ${r.validation.length} validation. ${d.message||''}`,action:'Add reviewed feedback in Data workspace'};if(!state.settings.enabled)return {status:'Policy paused',message:'Reviewed data is available. Enable the recovery policy to train.',action:'Review Settings'};return {status:d.confirmed?'Performance degradation detected':'Ready for evaluation',message:d.message+' Feature drift alone does not trigger training. A manual evaluation can also be requested.',action:d.confirmed?'Automatic recovery eligible':'Run reviewed-data recovery'}};
function activeVersion(){const o=ops();state.champion=o.champion;state.candidate=o.candidate;state.canary=!!o.canary}
async function trainCandidate(manual=false){const o=ops(),r=readiness();if(operationsBusy||o.canary||o.candidate)return;if(!state.settings.enabled){toast('Enable recovery policy first.');return}if(!r.ok){toast('Add enough reviewed train and validation examples of both classes.');return}if(!manual&&!deterioration().confirmed)return;const wait=state.settings.cooldown*60000;if(Date.now()-o.lastAttempt<wait){toast('Recovery cooldown is active.');return}o.lastAttempt=Date.now();o.lastFeedbackCount=o.feedback.length;operationsBusy=true;render();await new Promise(resolve=>setTimeout(resolve,30));try{const result=RecoveryEngine.train(trained,o.feedback,recoveryAssets,URLModel);const threshold=currentThreshold();const evaluation=RecoveryEngine.evaluate(trained,artifact(o.champion),result.artifact,o.feedback,recoveryAssets,URLModel,threshold);const id=`adaptive-${crypto.randomUUID().slice(0,8)}`;const version={id,parent:o.champion,createdAt:new Date().toISOString(),artifact:result.artifact,threshold,training:{rows:result.train_rows,replay:result.replay_rows,epochs:result.epochs,loss:result.loss},evaluation,status:evaluation.pass?'Candidate':'Rejected',feedbackIds:r.train.map(x=>x.id),validationIds:r.validation.map(x=>x.id)};o.versions[id]=version;o.jobs.unshift({id,time:version.createdAt,status:version.status,automatic:!manual});if(evaluation.pass)o.candidate=id;activeVersion();event(evaluation.pass?'Candidate passed independent gates':'Candidate rejected by evaluation',`${id}: actual residual-logistic training; ${result.train_rows} reviewed train / ${result.validation_rows} validation URLs.`,evaluation.pass?'info':'warning');}catch(err){operationsError=err.message;event('Recovery failed',err.message,'error')}finally{operationsBusy=false;save();render();if(o.auto&&o.candidate&&!o.canary)action('start-real-canary')}}
function rollback(reason='Operator requested rollback'){const o=ops();if(o.canary){const id=o.candidate;o.versions[id].status='Rolled back';o.candidate=null;o.canary=null}else if(o.previous){o.versions[o.champion].status='Rolled back';o.champion=o.previous;o.previous=null;if(o.versions[o.champion])o.versions[o.champion].status='Champion'}else return;activeVersion();event('Serving model rolled back',reason,'warning');save();render()}
function canaryEvidence(){const o=ops();if(!o.canary)return null;const rows=o.feedback.filter(r=>Date.parse(r.predictionTime)>=Date.parse(o.canary.startedAt)&&Date.parse(r.createdAt)>=Date.parse(o.canary.startedAt));const old=RecoveryEngine.metrics(rows,x=>RecoveryEngine.probability(trained,artifact(o.champion),x,URLModel),o.canary.threshold),candidate=RecoveryEngine.metrics(rows,x=>RecoveryEngine.probability(trained,artifact(o.candidate),x,URLModel),o.canary.threshold);return {rows:rows.length,both:new Set(rows.map(r=>r.y)).size===2,old,candidate,pass:rows.length>=20&&new Set(rows.map(r=>r.y)).size===2&&candidate.error<=old.error&&candidate.fnr!==null&&candidate.fnr<=Math.max(.1,old.fnr||0)}}
function checkCanary(){const o=ops();if(!o.canary)return;if(o.canary.threshold!==currentThreshold()){rollback('Policy threshold changed during canary; trial cancelled.');return}const e=canaryEvidence();if(e.rows>=10&&e.candidate.error>e.old.error+.05){rollback('Automatic rollback: reviewed candidate error exceeds champion by more than 5 percentage points.');return}if(e.pass&&o.auto)promote()}
function promote(){const o=ops(),e=canaryEvidence();if(!e?.pass){toast('Promotion needs 20 new reviewed observations, both classes, and passing error/FNR checks.');return}o.previous=o.champion;if(o.versions[o.champion])o.versions[o.champion].status='Archived';o.champion=o.candidate;o.versions[o.champion].status='Champion';o.versions[o.champion].canaryResult=e;o.candidate=null;o.canary=null;activeVersion();event('Model promoted into local serving',`${o.champion}: actual classifier now serves new requests. ${e.rows} reviewed canary observations.`);render()}
async function acceptFeedback(records){if(!trained||!recoveryAssets)throw Error('Wait for the model and recovery assets to load.');const o=ops(),seen=new Set(o.feedback.map(r=>r.url));const pending=[];for(const r of records){const url=String(r.url||'').trim(),evidence=String(r.evidence||'').trim(),reviewer=String(r.reviewer||'').trim();if(seen.has(url))throw Error('This URL already has a locked reviewed label: '+url);if(![0,1].includes(Number(r.label))||String(r.label).trim()==='')throw Error('Labels must be 0 or 1.');if(evidence.length<8||reviewer.length<2)throw Error('Every label needs an evidence reference (8+ characters) and reviewer name.');const x=URLModel.extract(url);const observed=state.predictions.find(p=>p.url===url);pending.push({id:crypto.randomUUID(),url,x,y:Number(r.label),evidence,reviewer,role:RecoveryEngine.partition(url,recoveryAssets),group:RecoveryEngine.group(url),createdAt:new Date().toISOString(),predictionTime:observed?.time||null,observedFlag:observed?.flag,observedModel:observed?.model});seen.add(url)}if(o.feedback.length+pending.length>1000)throw Error('Workspace limit is 1,000 reviewed URLs.');o.feedback.push(...pending);event('Reviewed labels accepted',`${pending.length} reviewer-attested labels; no independent authenticity check is performed.`);recordAssessment();save();checkCanary();render();if(o.auto&&o.feedback.length>o.lastFeedbackCount&&!o.candidate&&!o.canary)await trainCandidate(false)}
const beforeOpsBind=bind,beforeOpsAction=action;
action=function(name){const o=ops();if(name==='train-reviewed'){trainCandidate(true);return}if(name==='start-real-canary'){if(!o.candidate||o.canary)return;const v=o.versions[o.candidate];if(v.threshold!==currentThreshold()){toast('Threshold changed since evaluation. Reject candidate and run evaluation again.');return}o.canary={startedAt:new Date().toISOString(),threshold:currentThreshold(),weight:state.settings.canary/100,requests:0,candidateRequests:0};v.status='Canary';activeVersion();event('Actual local canary routing started',`${o.candidate} receives ${state.settings.canary}% of new requests; all new reviewed observations are paired against both models.`);render();return}if(name==='promote-real'){promote();return}if(name==='rollback-real'){rollback();return}if(name==='discard-candidate'&&o.candidate&&!o.canary){o.versions[o.candidate].status='Discarded';o.candidate=null;activeVersion();event('Candidate discarded','A fresh evaluation is required before another serving trial.');render();return}if(name==='export-evidence'){download('sentineldrift-recovery-evidence.json',JSON.stringify({scope:'browser-local actual learning and serving',...o},null,2));return}beforeOpsAction(name)};
function percent(n){return n===null||n===undefined?'—':(100*n).toFixed(1)+'%'}
function recoverySummary(){const p=performance(),d=deterioration(),r=readiness();return `<div class="metrics">${metric('Reviewed labels',ops().feedback.length,'Reviewer-attested; evidence required','✓')}${metric('Observed prediction error',p.n?percent(p.error):'—',`${p.n} pre-review predictions with labels`,'⌁')}${metric('Training / validation',`${r.train.length} / ${r.validation.length}`,'Fixed host-group partition; both classes required','▤')}${metric('Degradation trigger',d.confirmed?'Detected':'Not reached',d.message||'Loading','⌇')}</div>`}
renders.recovery=function(){const o=ops(),d=decision(),last=o.jobs[0],v=last?o.versions[last.id]:null,e=canaryEvidence();return head('ACTUAL RECOVERY WORKSPACE','Review. Learn. Evaluate. Serve.','Real local learning and reversible browser serving. No simulated requests or outcomes.',btn('Train & evaluate','train-reviewed',true,operationsBusy||!readiness().ok||!state.settings.enabled||!!o.candidate||!!o.canary)+btn('Export evidence','export-evidence'))+recoverySummary()+panel('Current decision',`<div class="panel-body"><h3>${d.status}</h3><p>${d.message}</p><p class="help">Automatic recovery triggers when at least 30 previously scored URLs have reviewer-attested labels and measured error exceeds max(15%, historical error + 5 percentage points). Training and validation minima also apply.</p><a class="button" href="#data">Add reviewed feedback →</a></div>`)+panel('Independent evaluation',v?`<div class="panel-body"><h3>${v.id} · ${v.status}</h3><p>Actual training: ${v.training.rows} reviewed URLs + ${v.training.replay} historical replay rows; ${v.training.epochs} optimization epochs. Loss ${v.training.loss[0].toFixed(4)} → ${v.training.loss[1].toFixed(4)}.</p>${v.evaluation.checks.map(c=>`<div class="gate"><div><h3>${c.name}</h3><p>${c.detail}</p></div>${pill(c.pass?'Pass':'Rejected',c.pass?'':'red')}</div>`).join('')}<p class="help">Historical gate: 400 labeled benchmark rows, never used for residual training. Recent validation: held-out host groups. Repeated gate use can bias selection; this is not an untouched future-test claim.</p></div>`:'<div class="empty">No training run yet. The system will not invent a candidate when reviewed data is missing.</div>')+panel('Actual serving controls',`<div class="panel-body"><div class="summary-row"><span>Champion</span><strong>${esc(o.champion)}</strong></div><div class="summary-row"><span>Candidate</span><strong>${esc(o.candidate||'None')}</strong></div>${o.canary?`<p>Canary allocation: ${o.canary.weight*100}%. Actual requests: ${o.canary.requests}; served by candidate: ${o.canary.candidateRequests}.</p><p>New reviewed paired observations: ${e.rows}/20 · champion error ${percent(e.old.error)} · candidate error ${percent(e.candidate.error)} · both classes ${e.both?'present':'needed'}.</p>`:''}<div class="actions">${btn('Start canary','start-real-canary',true,!o.candidate||!!o.canary)}${btn('Promote','promote-real',false,!e?.pass)}${btn('Rollback','rollback-real',false,!o.canary&&!o.previous)}${btn('Discard candidate','discard-candidate',false,!o.candidate||!!o.canary)}</div><p class="help">During canary, a real random share of new analysis requests uses the trained candidate. At 10 reviewed observations, excess candidate error triggers rollback. At 20 with both classes and passing guards, automatic mode promotes. These small-sample policies are prototype guardrails, not production statistical assurance. Serving state is local to this browser, not a cloud fleet.</p></div>`)+panel('Training history',`<div class="panel-body">${o.jobs.length?o.jobs.map(j=>`<div class="activity"><div><h3>${esc(j.id)}</h3><p>${esc(o.versions[j.id].status)} · ${j.automatic?'Automatic':'Manual'} · ${new Date(j.time).toLocaleString()}</p></div></div>`).join(''):'No completed training jobs.'}</div>`)};
const previousData=renders.data;
renders.data=function(){const feedback=ops().feedback;return head('REVIEWED FEEDBACK','Give the model checked answers.','The website records reviewer attestation; it cannot independently prove your label is correct.')+panel('Review a URL',`<form id="review-form" class="panel-body"><div class="field"><label for="review-url">URL</label><input id="review-url" type="url" required placeholder="Paste a previously analyzed URL"></div><div class="field"><label for="review-label">Checked label</label><select id="review-label"><option value="">Choose a label</option><option value="1">Phishing (1)</option><option value="0">Legitimate (0)</option></select></div><div class="field"><label for="review-source">Evidence / trusted-source report reference</label><input id="review-source" required minlength="8" maxlength="500" placeholder="Report identifier or evidence reference"></div><div class="field"><label for="reviewer">Reviewer name / ID</label><input id="reviewer" required minlength="2" maxlength="80"></div><div class="field"><label><input type="checkbox" id="review-attest" required> I checked this label independently of this model's prediction.</label></div><button class="button primary" type="submit">Save reviewed label</button><p id="review-error" class="error" role="alert"></p><p class="help">One locked label per exact URL. Training/validation roles are assigned by hostname group and do not change on repeat runs. Review history is browser-local.</p></form>`)+panel('Import reviewed labels',`<form id="review-import" class="panel-body"><label for="review-file">CSV · columns url,label,evidence,reviewer · maximum 1 MB</label><input id="review-file" type="file" accept=".csv,text/csv" required><div class="field"><label><input type="checkbox" id="import-attest" required> I attest these labels were independently reviewed, not generated by this model.</label></div><button class="button" type="submit">Import reviewed CSV</button><p id="import-error" class="error" role="alert"></p></form>`)+panel('Locked review history',`<div class="table-wrap"><table><thead><tr><th>URL</th><th>LABEL</th><th>ROLE</th><th>EVIDENCE</th><th>REVIEWER</th></tr></thead><tbody>${feedback.slice(-100).reverse().map(f=>`<tr><td style="overflow-wrap:anywhere">${esc(f.url)}</td><td>${f.y?'Phishing':'Legitimate'}</td><td>${f.role}</td><td>${esc(f.evidence)}</td><td>${esc(f.reviewer)}</td></tr>`).join('')}</tbody></table></div>`)};
const beforeMonitoring=renders.monitoring;
renders.monitoring=()=>beforeMonitoring()+panel('Measured errors from reviewed predictions',`<div class="panel-body">${recoverySummary()}<p class="help">Errors compare saved prediction-time decisions to reviewer-attested labels. They are not inferred from suspicious URL structure. Historical predictions stay tied to the model and threshold that served them.</p></div>`);
const beforeModels=renders.models;
renders.models=()=>beforeModels()+panel('Adaptive serving versions',`<div class="panel-body"><h3>Current serving champion: ${esc(ops().champion)}</h3><p>Adaptive versions preserve the frozen RF base and learn a logistic residual correction from reviewed labels. They are real fitted parameter artifacts, not a full Random Forest rebuild.</p>${Object.values(ops().versions).map(v=>`<div class="result"><h3>${esc(v.id)} · ${esc(v.status)}</h3><p>Parent: ${esc(v.parent)} · ${v.artifact.weights.length} learned weights + bias · threshold ${v.threshold}</p><p>Historical gate F1 ${v.evaluation.historical.f1.toFixed(4)} · recent validation F1 ${v.evaluation.recent.f1.toFixed(4)}</p></div>`).join('')||'<p>No adaptive version trained yet.</p>'}</div>`,btn('Export model artifacts','export-evidence'));
const beforeSettings=renders.settings;
renders.settings=()=>panel('Automatic recovery',`<form id="automation-form" class="panel-body"><label><input type="checkbox" id="auto-recovery" ${ops().auto?'checked':''}> Automatically train on confirmed degradation, start a passed candidate's canary, and promote after reviewed canary evidence.</label><p class="help">Only reviewer-attested labels count. Cooldown, independent gates, and canary checks remain enforced. Disabling this does not disable automatic safety rollback.</p><button class="button" type="submit">Save automation policy</button></form>`)+beforeSettings().replaceAll('Reserved for future canary serving; does not affect predictions.','Share of actual new requests served by a candidate during canary (1–50%).').replaceAll('Reserved for future training jobs; no automatic retraining is connected.','Minimum minutes between actual training attempts.');
bind=function(){beforeOpsBind();if($('review-form'))$('review-form').onsubmit=async e=>{e.preventDefault();try{if(!$('review-attest').checked)throw Error('Independent review attestation is required.');await acceptFeedback([{url:$('review-url').value,label:$('review-label').value,evidence:$('review-source').value,reviewer:$('reviewer').value}]);toast('Reviewed label saved; monitoring and recovery updated.')}catch(err){if($('review-error'))$('review-error').textContent=err.message}};if($('review-import'))$('review-import').onsubmit=async e=>{e.preventDefault();try{if(!$('import-attest').checked)throw Error('Review attestation is required.');const file=$('review-file').files[0];if(!file||file.size>1024*1024)throw Error('Choose a CSV smaller than 1 MB');const rows=parseCSV((await file.text()).replace(/^\uFEFF/,''));const headers=rows.shift()?.map(s=>s.trim().toLowerCase())||[];const required=['url','label','evidence','reviewer'];if(required.some(h=>!headers.includes(h))||new Set(headers).size!==headers.length)throw Error('CSV needs unique headers: url,label,evidence,reviewer');if(!rows.length||rows.length>1000)throw Error('Import 1–1000 rows');await acceptFeedback(rows.map(row=>{if(row.length!==headers.length)throw Error('CSV column count mismatch');return Object.fromEntries(required.map(h=>[h,row[headers.indexOf(h)]]))}));toast('Reviewed labels imported.')}catch(err){if($('import-error'))$('import-error').textContent=err.message}};if($('automation-form'))$('automation-form').onsubmit=e=>{e.preventDefault();ops().auto=$('auto-recovery').checked;event('Automation policy changed',ops().auto?'Automatic training/promotion enabled':'Manual training/promotion selected');render()};if($('settings-form')){$('risk-threshold').min=Math.ceil((trained?.policy?.high||.87)*100);const submit=$('settings-form').onsubmit;$('settings-form').onsubmit=e=>{submit(e);checkCanary()}}};
ops();activeVersion();document.querySelector('footer').innerHTML='<span>SentinelDrift / Reviewed-data recovery</span><span>Multi-source classifier · v0.4</span>';document.querySelector('.notice').innerHTML='<span>◈</span><span><strong>Local recovery workspace.</strong> Reviewed feedback drives real training, independent gates, canary routing and rollback. Reviewer evidence is attested, not automatically verified. No cloud model fleet is deployed.</span>';
fetch('recovery-data.json').then(r=>{if(!r.ok)throw Error('Recovery data download failed');return r.json()}).then(a=>{if(!a.replay?.length||!a.historical_gate?.length)throw Error('Invalid recovery assets');recoveryAssets=a;save();render()}).catch(e=>{operationsError=e.message;render()});render();
